// Settings: where Landflow's API is (the HTTP nodes use the Landflow API key), who pays and who answers for the agents.
const LANDFLOW_URL = 'http://localhost:3000';
const COST_CENTER = 'ENG-AGENTS';
const SPONSOR = 'eden.tzur@landbright.test';  // the person accountable for the agents (not an approver)
const THRESHOLD = 0.8;                         // ask once an agent has spent this share of its monthly cap
const RAISE_BY = 1.5;                          // a new cap of at least this times the old one…
const HEADROOM = 1.2;                          // …and at least this times the month's forecast

const now = new Date();
const monthStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
const month = monthStart.toISOString().slice(0, 7);
// One item per agent that made AI calls in this batch.
const agentIds = [...new Set(items.map((i) => i.json.agentId).filter(Boolean))];
return agentIds.map((agentId) => ({
  agentId, landflowUrl: LANDFLOW_URL.replace(/\/+$/, ''), costCenter: COST_CENTER, sponsor: SPONSOR,
  threshold: THRESHOLD, raiseBy: RAISE_BY, headroom: HEADROOM, month, monthStart: monthStart.toISOString(),
}));

// One item per agent over the threshold of its monthly cap, with the forecast and the cap to ask for.
const settings = $('Settings').all();
const agents = $('Read the agent').all();
const out = [];
items.forEach((usage, i) => {
  const s = settings[i].json;
  const agent = agents[i].json.agent;
  if (!agent) return;
  // The published version's caps are the ones enforced.
  const caps = agent.published?.config?.settings ?? agent.settings ?? {};
  const cap = Number(caps.monthlyCostLimit ?? 0);
  if (!(cap > 0)) return; // no monthly cap: nothing to raise
  const spent = Number(usage.json.totals?.cost ?? 0);
  if (spent < cap * s.threshold) return;
  const start = Date.parse(s.monthStart);
  const end = Date.UTC(new Date(start).getUTCFullYear(), new Date(start).getUTCMonth() + 1, 1);
  const elapsed = Math.max(Date.now() - start, 24 * 3600 * 1000);
  const forecast = spent * (end - start) / elapsed;
  const newCap = Math.ceil(Math.max(cap * s.raiseBy, forecast * s.headroom));
  out.push({
    ...s,
    agentName: agent.name,
    cap,
    spent: Math.round(spent * 100) / 100,
    forecast: Math.round(forecast * 100) / 100,
    newCap,
    extra: (newCap - cap).toFixed(2),
    share: Math.round((spent / cap) * 100),
    evidence: {
      lines: [{ label: `Raise ${agent.name}'s monthly AI cap from $${cap} to $${newCap}`, amount: (newCap - cap).toFixed(2) }],
      basis: `Spent $${spent.toFixed(2)} of a $${cap} cap (${Math.round((spent / cap) * 100)}%) by ${new Date().toISOString().slice(0, 10)}; at this pace the month ends near $${forecast.toFixed(2)}.`,
      links: [{ label: `${agent.name} in Landflow`, url: `${s.landflowUrl}/agents/${agent.id}` }],
      match: { agent: agent.id },
      agentId: agent.id,
      cap,
      spent: Math.round(spent * 100) / 100,
      forecast: Math.round(forecast * 100) / 100,
      newMonthlyCap: newCap,
    },
  });
});
return out;

