// Check the approved request against the agent before changing it: the agent it names, a sane new cap, and no
// unpublished draft edits (publishing would ship them too: those wait for a person).
const s = $('Raise settings').first().json;
const request = $('Get the request').first().json.request;
const agent = $input.first().json.agent;
const newCap = Number(request.evidence?.newMonthlyCap ?? 0);
const published = agent?.published?.config;
const same = (a, b) => JSON.stringify(a ?? null) === JSON.stringify(b ?? null);
const draftChanged = published ? Object.keys(published).some((k) => !same(agent[k], published[k])) : false;
const oldCap = Number((published?.settings ?? agent?.settings ?? {}).monthlyCostLimit ?? 0);
let why = '';
if (request.requester?.kind !== 'agent' || !agent || agent.id !== request.requester.agent?.id) why = 'The request does not name this agent';
else if (!(newCap > oldCap)) why = `The new cap ($${newCap}) is not above the current one ($${oldCap})`;
else if (newCap > s.maxCap) why = `The new cap ($${newCap}) is above the flow's limit ($${s.maxCap})`;
else if (draftChanged) why = `${agent.name} has unpublished changes: raise the cap by hand, then mark the request applied`;
return {
  ok: !why, why, requestId: request.id, number: request.number, agentId: agent?.id ?? null, agentName: agent?.name ?? null,
  landflowUrl: s.landflowUrl, oldCap, newCap, publish: Boolean(published),
  settings: { ...(agent?.settings ?? {}), monthlyCostLimit: newCap },
};
